mapper.sql:
AND (
    i.family_id = #{visible.familyId}

        AND (i.created_by = #{visible.authorId}

             OR i.visibility IN
             #{v}

        )


        OR EXISTS (SELECT 1 FROM content_audience ca
                    WHERE ca.content_type = 'item' AND ca.content_id = i.id
                      AND ca.target_type = 'FAMILY' AND ca.target_id = #{visible.familyId})

)

mapper.select:
SELECT i.id, i.family_id, i.name, IFNULL(i.aliases,'') AS aliases, IFNULL(i.position,'') AS position, IFNULL(i.image_url,'') AS image_url, IFNULL(i.type,'OTHER') AS type, IFNULL(i.visibility,'FAMILY') AS visibility, i.quantity, IFNULL(i.unit,'') AS unit, IFNULL(i.note,'') AS note, DATE_FORMAT(i.stored_at, '%Y-%m-%d %H:%i:%s') AS stored_at, i.shelf_life, IFNULL(i.shelf_life_unit,'') AS shelf_life_unit, i.rel_x, i.rel_y, i.room_id AS item_room_id, i.created_by, i.created_at, i.updated_at, COALESCE(r.id, ir.id) AS room_id, COALESCE(r.house_id, ir.house_id) AS house_id, COALESCE(r.name, ir.name) AS room_name, COALESCE(r.floor, ir.floor) AS floor, f.id AS furniture_id, f.name AS furniture_name, COALESCE(h.name, ih.name) AS house_name FROM family_item i LEFT JOIN family_furniture f ON i.furniture_id = f.id LEFT JOIN family_room r ON f.room_id = r.id LEFT JOIN family_house h ON r.house_id = h.id LEFT JOIN family_room ir ON i.room_id = ir.id LEFT JOIN family_house ih ON ir.house_id = ih.id WHERE 1 = 1
AND i.family_id = #{familyId}
AND i.type = #{type}
AND r.id = #{roomId}
AND f.id = #{furnitureId}
AND (i.name LIKE CONCAT('%', #{keyword}, '%') OR i.aliases LIKE CONCAT('%', #{keyword}, '%') OR i.position LIKE CONCAT('%', #{keyword}, '%') OR f.name LIKE CONCAT('%', #{keyword}, '%') OR r.name LIKE CONCAT('%', #{keyword}, '%') OR h.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY COALESCE(h.id, ih.id), COALESCE(r.floor, ir.floor), COALESCE(r.sort_order, ir.sort_order), COALESCE(r.id, ir.id), f.id, i.id

mapper.update:
UPDATE family_item
SET quantity = quantity - #{amount}
WHERE id = #{id}
  AND family_id = #{familyId}
  AND quantity IS NOT NULL
  AND quantity >= #{amount}
